{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Repeated-run testing is neither documented nor explicitly ruled out."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "70% in one reported run",
          "reason": "One reported score does not establish consistency across runs."
        }
      ],
      "instrument_review": "EFPA 9.3 and 9.7 are reinterpreted as consistency across repeated AI evaluations. Repeatability evidence warrants 0, insufficient information, rather than 1, inadequate performance. Section 10 limits interpretation to the stated grid-puzzle use."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "exactly once and did not repeat it",
          "reason": "The passage explicitly excludes repeated-run testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "70% in one reported run",
          "reason": "The absence of repetitions leaves score stability unknown; it does not demonstrate instability."
        }
      ],
      "instrument_review": "Under EFPA 9.3 and 9.7, reinterpreted for repeated AI runs, the explicit absence of repetitions establishes a study-design limitation. Repeatability remains rated 0 for insufficient evidence, rather than 1 for demonstrated poor consistency."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "The report documents repetitions with the specified conditions held constant."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's stability definition of at most two percentage points."
        }
      ],
      "instrument_review": "EFPA 9.7 accommodates the reported range as alternative precision evidence; 9.3 supplies the repeated-evaluation perspective. Stability is supported under the stated operational definition. Ten runs are not ten independent systems, and the range is not a reliability coefficient; broader precision adequacy remains unestablished."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated evaluations under the specified constant conditions are explicitly reported."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed variation exceeds the report's maximum stable range of two percentage points."
        }
      ],
      "instrument_review": "EFPA 9.7 distinguishes conducting a precision study from obtaining acceptable precision. The results demonstrate inadequate stability against the stated criterion, supporting 1 for that specific precision attribute. This is evidence of inconsistency, unlike missing repeatability evidence."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation guidance supplies no evidence that repeated-run testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added instructions provide no results demonstrating score consistency."
        }
      ],
      "instrument_review": "EFPA 6.3.8 concerns software instructions and technical support; installation guidance addresses part of that documentation domain. It supplies no new EFPA 9.3 or 9.7 precision evidence, which remains 0, insufficient information. Documentation and measurement quality require separate judgments."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "A achieved the higher observed score on the evaluated puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The findings provide no evidence establishing a cross-domain intelligence difference."
        }
      ],
      "instrument_review": "EFPA 3.2 and 10 support interpreting the observed scores within the stated grid-puzzle comparison. Sections 6.1 and 10.1 concern content coverage; 10.3 concerns relationships with other variables. No evidence supports extending this result across domains, but that extension is outside the stated intended use."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "The reported evaluation shows higher grid-puzzle performance for A."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "A broad intended use does not itself establish cross-domain validity."
        }
      ],
      "instrument_review": "EFPA 10 evaluates specific intended score interpretations. Here the intended selection use requires broader evidence than the grid results provide. Sections 6.1, 10.1 and 10.3 identify unresolved construct coverage and external validation. Cross-domain validity is unestablished; this does not prove the systems lack a general-intelligence difference. The critical validity gap invokes EFPA's restriction to research or exceptional expert use."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "Those scores alone do not establish improved real workshop decisions with A."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "Random allocation, blinded correctness checks and a difference interval of 12 to 28 percentage points support better correctness with A in the studied setting."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Decision correctness does not establish an effect on an unmeasured safety outcome."
        }
      ],
      "instrument_review": "EFPA 10.3.1.6 accommodates the randomized trial as experimental validity evidence for the workshop use; 10.3.2 also directs attention to relevant external outcomes. The trial adds evidence beyond initial scores. Its 120 inspectors concern the human assistance trial, not a sample of AI systems. Section 10.5 supports a scoped judgment about correctness, without extending it to safety, time or other workshops. EFPA correlation thresholds are not directly applied to the reported percentages."
    }
  ],
  "closing_note": "The requested brief case reviews clarify that full forms are unnecessary. All EFPA domains were considered for relevance; unreported norms, materials, reports and supply details were not invented or treated as proven defects. Human identity, sensory and motor prerequisites, and personal debriefing do not directly apply to AI systems; administration, repeatability and validity were explicitly reinterpreted for AI evaluation. Human-related questions remain relevant where inspectors participate in C8. Probe labels are separate from EFPA ratings. No aggregate quality score was calculated. The supplied extraction contains numbering and anchor ambiguities, but none affects these probes; the authoritative PDF was not consulted. Instrument source: EFPA Test Review Model 2025, version 5.0, https://www.efpa.eu/, CC BY-SA 4.0."
}
